import{_ as i,c as t,o as a,ae as l}from"./chunks/framework.DMK_uHmU.js";const o="/help-center/assets/messaging.C-CggDHa.png",m=JSON.parse('{"title":"Messaging Templates Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/global-settings/messaging.md","filePath":"Administration/Manage/global-settings/messaging.md"}'),n={name:"Administration/Manage/global-settings/messaging.md"};function s(r,e,c,d,u,p){return a(),t("div",null,e[0]||(e[0]=[l('<h1 id="messaging-templates-configuration-guide" tabindex="-1">Messaging Templates Configuration Guide <a class="header-anchor" href="#messaging-templates-configuration-guide" aria-label="Permalink to &quot;Messaging Templates Configuration Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Messaging Templates Configuration allows administrators to customize all system-generated communications sent to users. These communications include account invitations, verification codes, and multi-factor authentication (MFA) messages sent via email or SMS. By customizing these templates, you can ensure all system communications align with your organization&#39;s branding and communication style.</p><h2 id="accessing-messaging-templates" tabindex="-1">Accessing Messaging Templates <a class="header-anchor" href="#accessing-messaging-templates" aria-label="Permalink to &quot;Accessing Messaging Templates&quot;">​</a></h2><p><img src="'+o+'" alt="homepage"></p><p>The Messaging Templates configuration is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the Tenant Settings section and select &quot;Messaging&quot; from the menu.</p><h2 id="messaging-settings-interface-overview" tabindex="-1">Messaging Settings Interface Overview <a class="header-anchor" href="#messaging-settings-interface-overview" aria-label="Permalink to &quot;Messaging Settings Interface Overview&quot;">​</a></h2><p>The Messaging Settings interface consists of these key components:</p><ol><li><p><strong>Navigation Menu</strong>: Left sidebar with options for different message types</p><ul><li>Invitation</li><li>Verification</li><li>MFA</li><li>Help</li></ul></li><li><p><strong>Content Area</strong>: Main section that displays the template editor for the selected message type</p></li><li><p><strong>Help Section</strong>: Informational content explaining the purpose and usage of message templates</p></li></ol><p>Each message type has its own dedicated template editor with appropriate fields and options.</p><h2 id="message-template-types" tabindex="-1">Message Template Types <a class="header-anchor" href="#message-template-types" aria-label="Permalink to &quot;Message Template Types&quot;">​</a></h2><h3 id="invitation-templates" tabindex="-1">Invitation Templates <a class="header-anchor" href="#invitation-templates" aria-label="Permalink to &quot;Invitation Templates&quot;">​</a></h3><p>The Invitation template is used when a new user account is created. It provides login credentials and instructions for accessing the system for the first time.</p><p><strong>Available Fields:</strong></p><ol><li><p><strong>SMS Message</strong>:</p><ul><li>Used when sending invitations via text message</li><li>Must include <code>{username}</code> and <code>{####}</code> placeholders for username and temporary password</li><li>Example: <code>Your Sairis username is {username} and the temporary password is: {####}</code></li></ul></li><li><p><strong>Email Subject</strong>:</p><ul><li>Subject line for invitation emails</li><li>Example: <code>Your Company Name - Account Invitation</code></li></ul></li><li><p><strong>Email Body</strong>:</p><ul><li>HTML-formatted content for invitation emails</li><li>Rich text editor allows for formatted text, images, and layout customization</li><li>Must include <code>{username}</code> and <code>{####}</code> placeholders</li><li>&quot;Apply Branding&quot; button automatically creates a branded template</li></ul></li></ol><h3 id="verification-templates" tabindex="-1">Verification Templates <a class="header-anchor" href="#verification-templates" aria-label="Permalink to &quot;Verification Templates&quot;">​</a></h3><p>The Verification template is used when users need to verify their identity, such as during account recovery or when security policies require verification.</p><p><strong>Available Fields:</strong></p><ol><li><p><strong>SMS Message</strong>:</p><ul><li>Used when sending verification codes via text message</li><li>Must include <code>{####}</code> placeholder for the verification code</li><li>Example: <code>Your verification code is: {####}</code></li></ul></li><li><p><strong>Email Subject</strong>:</p><ul><li>Subject line for verification emails</li><li>Example: <code>Your Company Name - Account Verification</code></li></ul></li><li><p><strong>Email Body</strong>:</p><ul><li>HTML-formatted content for verification emails</li><li>Must include either <code>{####}</code> placeholder or <code>{##Verify Email##}</code> for clickable verification link</li><li>&quot;Apply Branding&quot; button automatically creates a branded template</li></ul></li></ol><h3 id="multi-factor-authentication-templates" tabindex="-1">Multi-Factor Authentication Templates <a class="header-anchor" href="#multi-factor-authentication-templates" aria-label="Permalink to &quot;Multi-Factor Authentication Templates&quot;">​</a></h3><p>The MFA template is used when multi-factor authentication is enabled, sending a verification code to the user&#39;s mobile device.</p><p><strong>Available Fields:</strong></p><ol><li><strong>SMS MFA Message</strong>: <ul><li>Text message sent during MFA challenges</li><li>Must include <code>{####}</code> placeholder for the verification code</li><li>Example: <code>Your authentication code is: {####}</code></li></ul></li></ol><h2 id="rich-text-editor" tabindex="-1">Rich Text Editor <a class="header-anchor" href="#rich-text-editor" aria-label="Permalink to &quot;Rich Text Editor&quot;">​</a></h2><p>The system includes a comprehensive rich text editor for customizing email templates with the following features:</p><ol><li><p><strong>Formatting Tools</strong>:</p><ul><li>Text styling (bold, italic, underline)</li><li>Font selection and sizing</li><li>Text and background color controls</li><li>Paragraph alignment options</li></ul></li><li><p><strong>Content Tools</strong>:</p><ul><li>Bulleted and numbered lists</li><li>Links and images</li><li>Tables for structured layout</li><li>Source code view for direct HTML editing</li></ul></li><li><p><strong>Preview Mode</strong>:</p><ul><li>Full-screen preview to see how the template will appear</li></ul></li></ol><h2 id="dynamic-placeholders" tabindex="-1">Dynamic Placeholders <a class="header-anchor" href="#dynamic-placeholders" aria-label="Permalink to &quot;Dynamic Placeholders&quot;">​</a></h2><p>Certain placeholders must be included in templates to provide personalized information to users:</p><ol><li><p><strong>Required Placeholders</strong>:</p><ul><li><code>{username}</code>: The user&#39;s login username</li><li><code>{####}</code>: Temporary password or verification code</li><li><code>{##Verify Email##}</code>: Creates a clickable verification link in email templates</li></ul></li><li><p><strong>Placeholder Usage</strong>:</p><ul><li>Placeholders must be entered exactly as shown, including braces</li><li>SMS templates require plain text with placeholders</li><li>Email templates can incorporate placeholders into HTML design</li></ul></li></ol><h2 id="branding-integration" tabindex="-1">Branding Integration <a class="header-anchor" href="#branding-integration" aria-label="Permalink to &quot;Branding Integration&quot;">​</a></h2><p>The system can automatically apply your organization&#39;s branding to message templates:</p><ol><li><p><strong>Apply Branding Button</strong>:</p><ul><li>Located in the top-right corner of each template editor</li><li>Generates a professionally designed template using your organization&#39;s: <ul><li>Company name from tenant settings</li><li>Primary brand colors</li><li>Logo (if configured)</li><li>System hostname for proper links</li></ul></li></ul></li><li><p><strong>Brand Elements Applied</strong>:</p><ul><li>Header with company logo/name</li><li>Branded color scheme matching your tenant settings</li><li>Footer with legal information</li><li>Responsive design for various devices</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective messaging templates:</p><ol><li><p><strong>Clear Communication</strong>:</p><ul><li>Keep instructions simple and straightforward</li><li>Prominently display important information (username, codes)</li><li>Include clear next steps for the user</li></ul></li><li><p><strong>Branding Consistency</strong>:</p><ul><li>Use the &quot;Apply Branding&quot; feature to maintain visual consistency</li><li>Ensure colors and styling match your organization&#39;s brand guidelines</li><li>Include your company logo in email communications</li></ul></li><li><p><strong>Mobile Optimization</strong>:</p><ul><li>Keep SMS messages concise (under 160 characters if possible)</li><li>Ensure email templates are responsive for mobile viewing</li><li>Test templates on different devices and email clients</li></ul></li><li><p><strong>Security Considerations</strong>:</p><ul><li>Do not include sensitive information beyond required credentials</li><li>Inform users about the expiration time for verification codes</li><li>Include contact information for support</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Placeholders not being replaced with actual values</p><ul><li>Verify the exact format of placeholders (<code>{username}</code> and <code>{####}</code>)</li><li>Check for extra spaces or characters in placeholders</li><li>Ensure placeholders are in the correct template (invitation vs. verification)</li></ul><p><strong>Issue</strong>: HTML formatting not appearing in sent emails</p><ul><li>Verify HTML syntax in the source code view</li><li>Test email in multiple email clients</li><li>Check for missing closing tags or invalid HTML</li></ul><p><strong>Issue</strong>: &quot;Apply Branding&quot; button doesn&#39;t update template</p><ul><li>Ensure tenant settings include company name</li><li>Verify branding colors are properly configured</li><li>Try toggling between template types and back</li></ul><p><strong>Issue</strong>: SMS messages too long</p><ul><li>SMS messages should ideally be under 160 characters</li><li>Consider abbreviating instructions</li><li>Focus only on essential information for SMS templates</li></ul><p><strong>Issue</strong>: Email template looks different when received</p><ul><li>Different email clients render HTML differently</li><li>Use simple, well-supported HTML elements</li><li>Test with major email clients (Gmail, Outlook, etc.)</li></ul><hr><p>For additional assistance with messaging template configuration, please contact your system administrator.</p>',50)]))}const h=i(n,[["render",s]]);export{m as __pageData,h as default};
